                    path = "/api/v1/" + plural if scope == "*" else f"/api/v1/namespaces/{quote(scope, safe='')}/{plural}"
                    jobs.append((imported_kind, scope, "kubernetes", lambda path=path, scope=scope, imported_kind=imported_kind:
