                item = discovered["items"][0] if discovered["items"] else {}
                version = item.get("serverVersion", {}).get("gitVersion", "")
                match = re.match(r"^v?([0-9]+)\.([0-9]+)", version)
                modern = bool(match and tuple(map(int, match.groups())) >= (1, 25))
